    "천국의 하나님의 보좌는 곧 거룩한 성전이므로 하나님께서 보좌 위에 직접 좌정하신 모양을 인간의 눈으로 볼 수는 없습니다.",
    "이는 하나님께서 회전하는 그림자도 없으신 말씀의 빛이시며 영이시기 때문입니다.",
    "하나님은 인격적인 육체로서 보좌 위에 앉아 계시는 분이 아니기에 천국의 불꽃 보좌는 그 자체로 하나님의 임재를 상징하며 존재합니다.",
    "보좌는 그 본질이 금이나 보석이나 상아 같은 귀중품으로 제작한 공예품이 아닙니다.",
    "보좌는 가장 위대한 인격자로서 한 인격이 네 종류의 인격을 가지고 있는 그룹이라 불리는 존재입니다.",
    "그 그룹 안에 하나님의 영광과 능력과 말씀 그리고 인격적인 모든 요소가 완전히 갖추어져 있는 것입니다.",
    "이러한 보좌의 성격을 말씀 안에서 구체적으로 고찰해 보아야 합니다.",
