    "또한 그 머리 뒤에 있는 궁창 위에 보좌의 형상이 있는데 그 모양이 남보석 같다고 하셨으며 ( 겔 1 : 26 ) 그룹들 머리 위 궁창에 남보석 같은 것이 나타나는데 보좌 형상 같더라고 기록되었습니다 ( 겔 10 : 1 ).",
    "보좌 앞에 수정과 같은 유리 바다가 있고 보좌 가운데와 보좌 주위에 네 생물이 있는데 앞뒤에 눈이 가득하더라는 요한의 고백도 이와 일맥상통합니다 ( 계 4 : 6 ).",
    " ",
    "## 그룹 안에 감추어진 하나님의 비밀과 통찰하시는 눈 ##",
    "다니엘과 에스겔 그리고 사도 요한이 환상 중에 본 보좌는 모두 똑같은 한 그룹을 가리키는 것입니다.",
    "전통적인 기독교 지식으로는 그룹을 그저 천사라고 부르는 정도에 머물러 그 이상의 깊은 진리를 알지 못했습니다.",
    "그러나 지금까지 우리가 알지 못했던 모든 하나님의 비밀은 바로 이 그룹 안에 감추어져 있었습니다.",
    "그 큰 비밀의 핵심을 밝히자면 그룹은 곧 여호와의 영광이며 ( 겔 10 : 4 ) 전능하신 하나님의 말씀이 담긴 처소입니다 ( 겔 10 : 5 ).",
