    "에스겔 28장에 등장하는 그룹에 대하여 기독교에서는 천사가 타락하여 사단이 된 것이라고 해석해 왔으나 성경은 그룹을 가리켜 하나님께서 기름 부어 세우신 사람이라고 분명히 명시하고 있습니다.",
    " ",
    "## 기름 부음 받은 그룹의 정체와 첫 사람 아담 ##",
