    "네 마음이 하나님의 마음과 같은 체할지라도 너는 사람이요 신이 아니어늘 하신 꾸중은 이를 뒷받침합니다 ( 겔 28 : 2 ).",
    "너를 살육하는 자 앞에서 네가 그래도 말하기를 내가 하나님이라 하겠느냐 너를 치는 자의 수중에서 사람뿐이요 신이 아니라는 말씀 또한 그룹의 본질이 인간임을 확증합니다 ( 겔 28 : 9 ).",
    "너는 완전한 인이었고 지혜가 충족하며 온전히 아름다웠도다 하신 기록은 그룹이 곧 사람이요 그 사람이 곧 사단이라는 사실을 명확히 밝히시는 것입니다 ( 겔 28 : 12 ).",
    "그렇다면 사람으로서 하나님인 체할 수 있는 위대한 인격자가 세상에 과연 누구이겠습니까.",
    "이는 틀림없이 하나님의 영광과 능력과 지혜와 말씀의 형상으로 지음을 받고 기름 부어 세우신 세상 임금 곧 첫 사람이 아담이 아니면 누구이겠습니까.",
    "너는 완전한 사람이라고 하신 것은 하나님의 성산 안에 있었던 완전한 인간이 첫 사람 아담 한 사람뿐이었기 때문입니다.",
    "그러므로 하나님의 보좌 곧 성전은 하나님의 형상대로 창조하신 첫 사람이 아니고서는 세움을 받을 만한 자가 없습니다.",
    "하나님의 섭리는 처음과 나중이 완벽하게 연결되어 있습니다.",
