    "그리하여 새 예루살렘에는 성안에 성전을 내가 보지 못하였으니 이는 주 하나님 곧 전능하신 이와 및 어린 양이 그 성전이심이라 하신 말씀처럼 이전의 그룹 보좌는 사라지고 참된 성전만이 남게 되는 것입니다 ( 계 21 : 22 ).",
