    "그리스도께서 우리를 위하여 저주를 받은 바 되사 율법의 저주에서 우리를 속량하셨다고 하셨습니다 ( 갈 3 : 13 ).",
    "또한 원수 된 것 곧 의문에 속한 계명의 율법을 자기 육체로 폐하셨으며 원수 된 것을 십자가로 소멸하셨습니다 ( 엡 2 : 15-16 ).",
