    "돌에 써서 새긴 죽게 하는 의문의 직분도 영광이 있어 정죄의 직분도 영광이 있은즉 의의 직분은 영광에 더욱 넘치리라 하신 말씀에서 정죄의 죽이는 의문의 직분을 받은 자가 바로 지음 받은 진노의 하나님이심을 알 수 있습니다 ( 고후 3 : 7-11 ).",
