    "또 한 가지는 타락한 천사가 사단이 되어서 하나님의 섭리를 방해하며 대적하고 있는 정도로만 알고 세상을 통치하는 하나님의 사자라는 사실을 알지 못하기 때문에 세상 유혹을 받기 쉬운 이유가 여기에 있는 것입니다 ( 롬 13:1-7 ).",
    "이상의 말씀의 주인공인 세상 임금은 전통적 교리에서 가르치는 천사가 타락한 사단은 물론 아니고 참 사단은 세상 신 곧 세상 임금이며 거짓 하나님이라고 하는 것입니다.",
    "이는 참 하나님이 계신 즉 거짓 하나님이 있고 참 사단이 있은 즉 거짓 사단도 있는 것입니다 ( 요 17:3 ) ( 겔 28:1 ).",
