    "그러므로 세상 사람들이 누리는 모든 축복은 사실 세상 주관자인 아담 안에서 받은 것입니다.",
    "주님께서 가이사의 것은 가이사에게 바치고 하나님의 것은 하나님께 바치라고 하신 말씀의 깊은 뜻이 여기에 있습니다.",
  "## 세상의 정욕과 천국 백성의 유업 ##",
    "이는 세상에 있는 모든 것이 육신의 정욕과 안목의 정욕과 이생의 자랑이니 다 아버지께로 좇아온 것이 아니요 세상으로 좇아온 것이라 하였습니다 ( 요일 2:16 ).",
    "간음하는 여자들 곧 신도들이여 세상과 벗된 것이 하나님과 원수임을 알지 못하느뇨 그런즉 누구든지 세상과 벗이 되고자 하는 자는 스스로 하나님과 원수 되게 하는 것이라 하셨으니 이는 세상 임금의 권세에 머무는 자의 위태함을 경고하신 것입니다 ( 약 4:4 ).",
    "그런고로 주님께서는 심령이 가난한 자가 복이 있나니 천국이 저희 것임이라 하고 가르치셨습니다 ( 마 5:2-3 ).",
