    "사도행전을 보면 빌립이 사마리아 성에서 많은 사람에게 붙었던 귀신을 내어 쫓고 많은 병자의 병을 낫게 하는 표적을 행하였으나 그는 물 세례만 주는 사명자였으므로 성령 세례는 베풀지 못하였습니다 ( 행 8:5-16 ) .",
    "이후 베드로와 요한 두 사도가 저희에게 안수하매 비로소 성령을 받았습니다.",
