    "은사는 천사를 통하여 기사와 이적의 능력을 나타내지만 보혜사께서는 은밀하게 역사하시되 오직 진리의 말씀으로 하나님의 섭리의 비밀을 밝혀 드러내십니다.",
    "보혜사 곧 아버지께서 내 이름으로 보내실 성령 그가 너희에게 모든 것을 가르치시고 내가 너희에게 말한 모든 것을 생각나게 하시리라 하셨습니다 ( 요 14:26 ) .",
    " ",
    "## 진리의 말씀으로 인침 받는 성도 ##",
