    "보혜사의 성전으로 인침 받은 성도는 예수가 산에 임했다거나 광야에 임했다는 미혹의 소리가 들려와도 결코 미혹되지 않습니다.",
    "하나님의 아들의 영과 종의 영은 눈으로 보아서 분별하는 것이 아니라 오직 계시의 말씀 곧 십자가의 도인 보혜사 안에서만 분별하여 알 수 있는 것입니다.",
    "모든 천사들은 부리는 영으로서 구원을 얻을 후사들을 위하여 섬기라고 보내심을 받은 존재입니다 ( 히 1:14 ) .",
