    "천사 숭배함을 인하여 너희 상을 빼앗지 못하게 하라는 경고를 잊지 말아야 합니다 ( 골 2:18 ) .",
    "모든 은사는 하나님의 사자를 통해 주어지는 믿음의 표적이지 약속의 보혜사 성령 그 자체가 아닙니다.",
    "사도 요한이 천사의 발 앞에 경배하려 했을 때 천사는 자신을 함께 된 종이라 칭하며 오직 하나님께 경배하라 하였습니다 ( 계 22:8-9 ) .",
