    "가장 중요한 비밀은 선악을 알게 하는 나무에 있습니다.",
    "나무가 스스로 선악을 알게 할 수는 없기에 이는 선악을 아는 인격자인 아담 자신을 상징하는 나무이며 생명 나무는 곧 예수님을 상징합니다.",
    "선악을 알게 하는 나무의 실과는 먹지 말라 네가 먹는 날에는 정녕 죽으리라 하신 말씀은 아담의 계명의 법이 결국 진노와 사망만을 가져옴을 뜻합니다 ( 창 2:17 ) .",
    "이는 아담이 자신의 율법 열매를 취함으로 말미암아 육체의 죽음뿐만 아니라 영혼이 불못에 들어가는 둘째 사망에 이르게 됨을 경고하신 것입니다.",
    " ",
    "## 뱀의 비유와 인간 내면의 미혹 ##",
    "성경 창세기 삼 장의 말씀을 보면 뱀이 먼저 여자에게 말을 건네는 장면이 나옵니다.",
    "우리는 여기서 뱀이 어떻게 말을 할 수 있었는지에 대해 깊은 의문을 가져야 합니다.",
    "본래 하나님의 말씀을 받은 존재는 피조물 가운데 오직 사람뿐이기 때문입니다.",
    "이는 기록된 말씀 안에 깊은 신령한 비밀이 감추어져 있음을 뜻하므로 우리는 이를 세밀히 고찰해 보아야 합니다.",
    "성경 말씀 안에는 하나님의 말씀뿐만 아니라 사람과 천사와 사단의 말이 모두 기록되어 있으나 이 전부를 하나님의 말씀이라고 부르는 이유는 하나님만이 절대적인 능동자이시고 사람과 천사와 사단은 모두 그분의 뜻에 움직이는 수동자이기 때문입니다.",
    "그러므로 전능하신 하나님 앞에서 누가 무슨 말을 하든지 혹은 어떤 행동을 하든지 간에 이는 모두 하나님의 거격한 뜻 안에서 이루어지는 일입니다.",
    "에덴동산 안에 있는 모든 것은 아담의 소유이며 아담은 하나님의 소유입니다.",
