    "본문에서 뱀이 가장 간교하다고 하였는데 이 간교함이라는 속성은 오직 사람에게만 속한 것입니다.",
    "주님께서 너희는 뱀같이 지혜로우라고 말씀하신 것은 지혜와 간교함이 모두 첫 아담에게 속한 것임을 가르쳐 줍니다 ( 마 10:16 ).",
    "하나님의 지혜의 형상대로 지음을 받은 자는 오직 첫 아담 한 사람뿐이기 때문입니다.",
    "여자가 그 나무를 본즉 먹음직도 하고 보암직도 하고 지혜롭게 할 만큼 탐스럽기도 한 나무인지라 여자가 그 실과를 따먹고 자기와 함께 한 남편에게도 주매 그도 먹은지라 하신 말씀은 제삼자인 뱀이 밖에서 여자를 꾀어낸 것이 아니라 여자 자신의 마음 안에서 미혹이 일어났음을 의미합니다 ( 창 3:6 ).",
    "예사로운 이치로 생각할 때 여자의 앞에 과실나무가 있고 그 곁에 남편이 서 있다면 여자의 안목에 무엇이 더 탐스럽게 보이겠습니까.",
    "지혜롭게 할 만큼 탐스러운 존재는 나무가 아니라 바로 하나님의 형상인 남편입니다.",
    "여자는 자신의 지혜인 남편의 실과를 취하고 그 사랑을 나누고 싶은 심정에서 그 길을 택한 것입니다.",
  "## 에덴에서의 추방과 세상 통치권의 실현 ##",
    "그가 그 손을 들어 생명나무 실과도 따먹고 영생할까 하노라 하신 말씀은 근본적으로 아담의 인격 안에 영생이 없었기에 필경 죽을 수밖에 없는 존재임을 뜻합니다 ( 창 3:22 ).",
    "이같이 하나님이 그 사람을 쫓아내시고 하신 것은 아담을 지구 밖으로 내쫓으신 것이 아닙니다 ( 창 3:24 ).",
    "이는 적은 에덴인 레바논 산에서 큰 에덴인 지구 전체로 내보내어 생육하고 번성하여 땅에 충만하라는 축복의 말씀을 실현하게 하신 거룩한 조치입니다.",
    "에덴동산 동편에 그룹들과 두루 도는 화염검을 두어 생명나무의 길을 지키게 하시니라 하신 말씀에서 그룹은 곧 사람을 의미합니다 ( 창 3:24 ).",
    "하나님의 마음과 같은 체하는 존재인 그룹은 곧 하나님의 형상대로 지음 받은 아담입니다.",
    "여기서 화염검은 율법의 말씀의 검을 뜻하며 생명나무의 길은 주님의 생명을 뜻하므로 아담의 율법이 생명의 길을 지키는 역할을 맡게 된 것입니다.",
    "아담은 에덴동산을 다스리고 지키는 권세를 이미 부여받았기 때문입니다.",
    "따라서 땅의 만왕의 왕인 아담은 장차 재림하실 만왕의 왕 예수 그리스도의 표상이 됩니다 ( 롬 5:14 ).",
    " ",
    "## 살인자 가인과 율법 계보의 시작 ##",
    "가인이 동생 아벨을 쳐 죽이고 하나님 앞에서 쫓겨날 때 그가 만나는 자로부터 죽음을 당할까 봐 두려워한 까닭은 그의 아비 아담이 사망의 왕이기 때문입니다.",
    "가인의 배후에는 항상 사망의 두려움이 그림자처럼 따라다니고 있었던 것입니다 ( 창 4:14 ).",
    "동생을 죽인 자를 당연히 처형해야 함에도 불구하고 하나님께서 가인을 죽이는 자는 벌을 칠 배나 받으리라 하시며 표를 주어 죽임을 면케 하신 뜻은 무엇입니까 ( 창 4:15 ).",
    "주님께서는 마귀를 처음부터 살인한 자라고 하셨는데 성경 역사상 최초의 살인자는 가인뿐입니다 ( 요 8:44 ).",
    "이는 가인이 율법의 심판과 사망의 사역을 담당하는 계보의 시작임을 암시합니다.",
    "가인이 놋 땅에서 결혼할 수 있었던 것은 모든 족속이 아담 한 사람의 혈통에서 나왔기 때문입니다 ( 창 4:16 ).",
    "당시 사람의 수명은 구백 년 가까이 장수하였으므로 가인의 처 또한 동일한 아담의 혈통임이 분명합니다.",
    "가인을 위하여는 벌이 칠 배일진대 라멕을 위하여는 벌이 칠십 칠 배이리라 하신 말씀은 가인의 족속이 율법의 사명자로서 아담의 계보에서 갈라져 나왔음을 보여줍니다 ( 창 4:24 ).",
    "아담의 계통에서는 아벨 대신 셋이라는 다른 씨를 주셔서 하나님과 동행하는 의인들이 출생하게 하셨으나 가인의 계통에서는 오직 율법의 진노 아래 있는 자들만이 이어지게 되었습니다.",
    "불순종한 죄인인 아담의 자손 중에서 아벨이나 에녹 같은 의인이 나올 수 있었던 것은 하나님이 아담을 완전하게 지으셨다는 증거입니다.",
    "이는 단순히 유전적인 종자의 원리를 초월하여 역사하시는 하나님의 신기한 능력을 나타냅니다.",
    " ",
    "## 하나님의 전능한 형상과 첫 아담 ##",
    "전능하신 하나님께서 전능한 형상대로 완전하게 첫 아담을 창조하셨다고 함은 진노의 능력으로서 모든 육체의 생명을 전멸하는 절대 능력을 뜻하는 것입니다.",
    "자비하신 사랑의 하나님께서 죄악 된 인간 세상에 대하여 직접적으로 진노하며 심판하시는 것이 아니라 진노의 사자인 아담 안에서 섭리하시는 것입니다.",
    "그러므로 하나님의 창조는 완전하고 계시는 정확한 것입니다.",
