    "본 말씀 자체가 하나님의 완전한 말씀이므로 그의 형상 곧 첫 사람도 완전한 창조주의 다음가는 으뜸으로 지음 받은 인격자인 것입니다.",
    " ",
    "## 아담 안에 잠재한 일곱 가지 인격적 요소 ##",
    "하나님의 형상 곧 사람 안에 잠재한 인격적 요소를 개별적 형상으로 분류하면 다음과 같은 진리가 나타납니다.",
    "첫째로 하나님은 곧 말씀이시므로 말씀의 형상으로 첫 사람을 창조하셨기 때문에 말씀을 받지 못한 동물은 사람과 대화를 할 수 없는 것입니다.",
    "둘째로 하나님은 곧 창조주이시므로 창조의 형상대로 첫 사람을 창조하셨기에 첫 사람은 위대한 창조력을 가지고 있습니다.",
    "셋째로 하나님은 곧 전능하시므로 전능의 형상으로 첫 사람을 창조하셨기에 땅을 정복할 능력을 소유한 것입니다.",
    "넷째로 하나님은 곧 입법자이시므로 계명의 법의 형상으로 첫 사람을 인격화하였기에 세상을 다스립니다.",
    "다섯째로 하나님은 곧 영광의 주이시므로 영광의 형상대로 첫 사람을 창조하셨기에 세상 신의 영광을 소유하고 있는 것입니다.",
    "여섯째로 하나님은 곧 만왕의 왕이시므로 만왕의 왕의 형상으로 첫 사람을 창조하셨기에 세상의 만왕의 왕인 것입니다.",
    "일곱째로 하나님은 곧 섭리자이시므로 섭리의 형상으로 첫 사람을 창조하셨기에 하나님의 섭리가 첫 사람 안에서 실행되고 성취되는 것입니다.",
    "하나님의 형상 곧 첫 사람은 우주의 중심 인물이며 우주를 다스리는 주관자로서 우주 안의 모든 피조물을 첫 사람의 통치하에 두신 것입니다 ( 창 1:28 ).",
    "이를 누가 감히 유혹하여 타락시켜서 하나님의 절대 섭리를 파괴시킬 수 있겠으며 그러한 반역자가 어디에 있겠습니까.",
    " ",
    "## 세상 통치권과 천사장의 변론 ##",
    "천사장 미가엘이 모세의 시체에 대하여 마귀와 다투어 변론할 때에 감히 훼방하는 판결을 쓰지 못하고 다만 말하되 주께서 너를 꾸짖으시기를 원하노라 하였거늘 하고 기록되어 있습니다 ( 유 1:9 ).",
    "이는 천사장의 권세로도 마귀에 대하여 감히 명령을 하지 못하는 이유를 보여줍니다.",
    "세상의 통치권은 첫 사람이 받았기 때문에 천사장의 권세가 천국에서는 마귀 곧 첫 사람보다 크지만 세상에 와서는 첫 사람 곧 마귀의 권세보다 적은 것입니다.",
    "천사장과 마귀가 모세의 시체 곧 썩은 냄새나는 것을 무엇에 쓰려고 서로 다투었겠습니까.",
    "사람의 추상적 생각은 느보산에서 죽은 모세의 육체를 의미하겠지만 사실은 그것이 아니라 모세가 받은 율법을 모세의 죽은 시체로 상징하며 비유한 것입니다.",
    "왜냐하면 율법의 권능은 사망이기 때문에 곧 시체라고 한 것입니다.",
    "율법을 가지고 둘이서 다투는 이유는 천국 백성이 세상에서 살면서 범죄할 때 그 죄를 법으로 다스려야 하기 때문입니다.",
    "세상의 법권은 첫 사람 곧 마귀가 가지고 있는 고로 세상 임금이 범죄자를 정죄하겠다고 할 때 천사장은 천국 백성을 자기가 다스릴 권세가 있다고 주장하며 서로 법권을 가지고 다투는 것입니다.",
    "대제사장 여호수아는 여호와의 사자 앞에 섰고 사단은 그의 우편에 서서 그를 대적하는 것을 여호와께서 내게 보이시니라 여호와께서 사단에게 이르시되 사단아 여호와가 너를 책망하노라 이는 불에서 꺼낸 그슬린 나무가 아니냐 하셨습니다 ( 슥 3:1-5 ).",
    "본 말씀은 사단의 불에서 연단을 다한 대제사장을 그만 그슬리고 해방시켜 달라고 천사장이 사단에게 요청하였으나 사단이 불응하므로 세 사람이 하나님 앞에 가서 송사를 하는 장면입니다.",
    "그러므로 세상 나라의 절대 통치권은 첫 사람이 주관하는 것입니다.",
    "그러나 첫 사람의 절대 주관은 바로 하나님의 절대 주관인 것이므로 유일신의 영광과 권세는 오직 하나로 통치되는 것입니다.",
    "창조주 유일신의 의지와 지혜와 권능과 능력 그리고 영광과 섭리의 형상으로 지음 받은 첫 사람이 세상의 유일한 임금이요 유일신의 사자인 것입니다.",
