    "비록 하늘에나 땅에나 신이라 칭하는 자가 있어 많은 신과 많은 주가 있으나 그러나 우리에게는 한 하나님 곧 아버지가 계시니 만물이 그에게서 났고 우리도 그를 위하며 또한 한 주 예수 그리스도께서 계시니 만물이 그로 말미암고 우리도 그로 말미암았느니라 하였습니다 ( 고전 8:5-6 ).",
