    "## 성전에 앉아 하나님 노릇 하는 대적의 영 ##",
    "저는 대적하는 자라 범사에 일컫는 하나님이나 숭배함을 받는 자 위에 뛰어나 자존하여 하나님 성전에 앉아 자기를 보여 하나님이라 하느니라 하신 말씀이 있습니다 ( 살후 2:4 ).",
    "이 자가 바로 이스라엘 대제사장과 장로 서기관 모든 백성들의 심령 안에 들어가서 역사하여 그들의 메시아를 십자가에 못 박게 한 대적의 영입니다.",
    "네 마음이 하나님 마음 같은체 할지라도 너는 사람이요 신이 아니어늘 하고 성경은 엄히 경고합니다 ( 겔 28:2 ).",
