    "그것은 하나님의 창조물 중에 으뜸이라 그것을 지은 자가 칼을 주었고 하신 말씀은 하마를 모형으로 사단을 상징한 것인데 피조물 중에 으뜸으로 지음을 받고 칼 곧 율법의 말씀을 받은 자는 아담 밖에 없습니다 ( 욥 40:19 ).",
