  "## 사망의 왕과 생명의 왕의 표상 ##",
    "보라 이 사람이 하고 말씀하신 영광과 능력의 그릇인 아담을 죽은 자로 보지 말고 산 자로 보아야 합니다 ( 창 3:22 ).",
    "그리하면 참 하나님의 영광을 보게 될 것입니다.",
    "아담은 재림하실 만왕의 왕 예수 그리스도의 표상인데 어찌 산 자의 표상이 죽은 자가 될 수 있겠습니까 ( 롬 5:14 ).",
