    "그러나 너희가 그때에는 하나님을 알지 못하여 본질상 하나님이 아닌 자들에게 종 노릇 하였더니 하신 말씀은 사도 바울 자신이 진리를 받기 전 율법의 권세 잡은 자를 주로 섬기었던 때를 말합니다 ( 갈 4:8 ).",
    "율법은 장차 오는 좋은 일의 그림자요 참 형상이 아니므로 하였습니다 ( 히 10:1 ).",
    "율법의 권세 잡은 아담은 최초부터 참 진리의 형상으로 지음을 받은 것이 아니고 율법의 형상으로 지음을 받았습니다.",
