    "## 먹고 마시는 행위의 영적 비밀 ##",
    "이에 대한 입증의 말씀으로 골로새서 이 장 십육 절에 그러므로 먹고 마시는 것과 절기나 초하루나 안식일을 이유로 누구든지 너희를 비판하지 못하게 하라 하셨습니다 ( 골 2:16 ).",
