    "이상의 말씀은 곧 창세기 삼 장 삼 절에 동산 중앙에 있는 나무의 실과는 하나님의 말씀에 너희는 먹지도 말고 만지지도 말라 너희가 죽을까 하노라 하셨느니라 하신 말씀과 뜻이 동일합니다 ( 창 3:3 ).",
    "이는 육체의 법인 계명의 율법의 실과를 먹으면 정녕 죽기 때문에 사망의 선고가 바로 율법인 것임을 드러냅니다.",
    " ",
    "## 믿음의 장성함과 진리의 양식 ##",
    "로마서 십사 장 이 절에 어떤 사람은 모든 것을 먹을 만한 믿음이 있고 믿음이 연약한 자는 채소만 먹느니라 하셨습니다 ( 롬 14:2 ).",
