    "로마서 십사 장 십칠 절에 하나님의 나라는 먹는 것과 마시는 것이 아니요 오직 성령 안에서 의와 평강과 희락이라 하셨습니다 ( 롬 14:17 ).",
    "율법의 은혜로 죄를 깨달아 아는 곧 뉘우치는 양심만 가지고는 천국에 가지 못하며 반드시 보혜사의 인치심을 받아야 구원을 받는다는 깊은 진리가 담겨 있습니다.",
