    "율법의 교훈은 적게 받든 많이 받든 간에 율법의 죽은 의로는 구원을 받지 못합니다.",
    "그러므로 동방의 의인 욥 같은 경건한 사람도 사단의 불의 연단을 받은 후에 회개하기를 내가 주께 대하여 귀로 듣기만 하였사오나 이제는 눈으로 주를 뵈옵나이다 하였습니다 ( 욥 42:5 ).",
