    "요한복음 십사 장 십육 절에 내가 아버지께 구하겠으니 그가 또 다른 보혜사를 너희에게 주사 영원토록 너희와 함께 있게 하시리니 하셨습니다 ( 요 14:16 ).",
    "이는 율법의 진노의 권세로서 두렵게 하는 영이 아니고 예수님 자신의 진리의 신을 모든 성도 각자에게 보내주시겠다는 약속입니다.",
    "요한계시록 삼 장 이십 절에 볼찌어다 내가 문 밖에 서서 두드리노니 누구든지 내 음성을 듣고 문을 열면 내가 그에게로 들어가 그로 더불어 먹고 그는 나로 더불어 먹으리라 하셨습니다 ( 계 3:20 ).",
