    "이와 같이 하나님께서 마귀를 창조하시되 최고 능력과 최고 교만한 왕으로 창조하셨기 때문에 마귀에게 이 세상과 공중을 통치하는 세상 신이요 세상 임금으로 세우신 것이 확실합니다 ( 요 14:30 ) ( 고후 4:4 ).",
    " ",
    "## 사단의 정체와 사람의 본질 ##",
    "전통 교리가 말하는 사단의 기원장이라고 하는 이사야 십사 장과 에스겔 이십팔 장에 사단의 정체는 사람이라고 명확히 밝히고 있습니다.",
