    "이 말씀 자체가 창조주 하나님의 능력과 영광의 모든 섭리인데 이 말씀이 죽거나 버림을 받을 수가 있겠습니까.",
    "만일 이 말씀이 땅에 떨어지고 말았다면 하나님의 섭리는 결코 이루어질 수 없는 것입니다.",
  "## 선악과와 생명나무의 영적 비밀 ##",
    "선악을 알게 하는 나무의 실과는 먹지 말라 네가 먹는 날에는 반드시 죽으리라 하시니라 하신 이 말씀이 계명인 것만은 전통 교리가 알지만 그 이상의 비밀은 알지 못하고 있습니다 ( 창 2:17 ).",
