    "여호와 하나님이 이르시되 보라 이 사람이 선악을 아는 일에 우리 중 하나같이 되었으니 그가 그의 손을 들어 생명나무 열매도 따먹고 영생할까 하노라 하셨습니다 ( 창 3:22 ).",
