    "하나님께서 만물을 육일 과정에서 창조를 마치시고는 보시기에 좋았더라 하신 말씀을 각 과정에 한 번씩 하셨고 그다음에 창조물 중에 으뜸으로 하나님의 형상 곧 첫 사람을 창조하신 후에는 보시기에 심히 좋았더라 하시며 일곱 번을 완전히 기뻐하셨습니다 ( 창 1:31 ).",
    " ",
    "## 율법의 인격화와 의인의 출현 ##",
