    "하나님께서 태초부터 만대를 명정하시고 주께서 수효대로 만상의 이름을 불러 이끌어 내신즉 주님의 섭리의 그릇인 첫 사람이 타락한 것이 결코 아닙니다.",
    "하나님의 형상 곧 선악을 아는 일에 하나님과 같이 된 유일한 아담으로 말미암아 비로소 악과인 가인과 선과인 아벨이 탄생하게 됨으로써 최초로 선과 악을 알게 된 것입니다.",
