    "단순히 아담이 불순종 죄로 말미암은 죄의 모체 아비가 되었다면 그의 씨는 모두 가인 같은 죄인만 나와야 할 터인데 아벨 같은 의인과 에녹 노아 욥 다니엘 다윗의 조상 아브라함 같은 의인이 출생할 리가 없는 것입니다.",
    "이로 보아서 죄악 유전설과 죄악 종자설도 전적으로 성립되지 않음을 알 수 있습니다.",
    " ",
    "## 하나님의 유일한 권능과 일원론적 진리 ##",
    "주께서 행하시는 일을 누가 막으리요 전능하신 절대자의 최대 존귀한 영광과 신성의 그릇인 아담을 유혹하여 타락시켰다고 하는 뱀 곧 마귀라고 하는 자가 과연 실지로 있었다면 그는 능히 창조주를 대적할 수 있는 능력을 소유한 자로 볼 수밖에 없는데 그가 누구에게서 그 능력을 받았겠습니까 ( 롬 13:1 ).",
    "유일신의 능력 외에 또 다른 능력자가 있다고 보면 사실은 본질적으로 다른 두 능력자가 대적하는 것이므로 실지로는 이원론이라는 결론이 나오기 때문에 이는 비진리인 것입니다.",
    "하나님께서 지으신 유일한 섭리의 그릇은 세상에 현현한 처음 계시이므로 아담 안에 있는 큰 비밀이 처음부터 오늘까지 만민의 눈에 숨겨졌던 것뿐입니다.",
