    "하나님의 거룩하신 뜻이 하나님의 형상 안에서 온전히 이루어지는 것이 진리입니다.",
    "진리는 거짓으로 변하지 않는 것을 의미합니다.",
    "첫 사람은 하나님의 본체의 형상이 아니고 세상에 현현한 장차 없어질 영광의 형상입니다 ( 고전 15:40-49 ).",
  "## 아담 안에 감추어진 뱀의 비밀 ##",
    "내 입에서 나가는 말도 이와 같이 헛되이 내게로 돌아오지 아니하고 나의 기뻐하는 뜻을 이루며 내가 보낸 일에 형통하리라 하셨습니다 ( 사 55:11 ).",
    "본 말씀과 같이 첫 사람에게 축복하신 말씀이 그대로 형통하게 하라고 작은 에덴 동산 곧 레바논 산에서 큰 에덴 동산 곧 지구라는 세상으로 내보내신 것입니다.",
