    "이 일을 누가 행하였느냐 누가 이루었느냐 누가 태초부터 만대를 명정하였느냐 나 여호와라 태초에도 나요 나중 있을 자에게도 내가 곧 그니라 하셨습니다 ( 사 41:4 ).",
    "기독교를 계시의 종교라 합니다.",
    "그러므로 처음도 계시요 나중도 계시입니다.",
    "하나님의 섭리는 뱀으로 시작하여 뱀으로 말미암아 인간 세상의 끝을 맺습니다.",
    "하나님의 섭리의 비밀은 뱀 안에 있은즉 창세기 삼 장에 있는 뱀과 요한계시록에 있는 뱀은 곧 마귀라고 하였는데 전통 신학적 교리가 가르치고 있는 말씀은 천사가 타락하여 마귀가 되었고 마귀가 반역자 사단이 되어 하나님을 반역하고 대적할 목적으로 하나님의 형상대로 지음을 받은 첫 사람을 유혹하여 범죄 타락시켰다고 하는 것이 인류 타락의 기원라 합니다.",
    " ",
    "## 선악을 아는 지능과 하나님의 형상 ##",
