    " ",
    "## 대속의 신비와 율법의 완성 ##",
    "아담은 땅을 정복하고 우주를 다스리는 전능자의 사자인데 누구를 두려워할 자가 있겠습니까.",
    "또한 아담은 모든 육체를 먹어 죽이는 자입니다.",
