    "전통 교리에서 주장하는 천사가 타락한 반역자가 감히 하나님의 거룩한 성업에 개입하여 하나님의 형상 곧 하나님의 경륜과 섭리의 그릇인 첫 사람을 파괴시킬 수가 있겠습니까.",
